  (* [comment removed for export] *)
  Lemma pma_D : forall regs m (pixd pixs : Z),
    (1 <= pixd < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 9 = Z_to_bv 64 pixs ->
    exists regs',
      msteps SEGS (mkst regs (0x8f860 : word) m rom) (mkst regs' (0x6d438 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x8f870 /\ getr regs' 8 = Z_to_bv 64 pixd /\ getr regs' 10 = Z_to_bv 64 pixs
      /\ regs_agree (fun r => In r [1; 8; 10]%list) regs regs'.
