Lemma pixt_new_frame : forall C A A' m m' pixd w h d cd data cv,
  pixt_new C A A' m pixd w h d cd data cv ->
  (forall x : word, (pixd <= u x < pixd + 64)%Z -> m' x = m x) ->
  (cd <> 0%Z -> forall x : word, (cd <= u x < cd + 24)%Z -> m' x = m x) ->
  pixt_new C A A' m' pixd w h d cd data cv.
Proof.
